      "mainEntity": [
        {
          "@type": "Question",
          "name": "Which school district has the highest child poverty rate?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Among districts with 500 or more children, Helena-West Helena School District, AR had the highest estimate in 2024 (66.5%). Estimates for districts this size can be off by many points, so read it as among the highest, not as an exact rank."
          }
        },
        {
          "@type": "Question",
          "name": "Is child poverty going down?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Nationally, yes: the official rate for children 5 to 17 was 20.6% in 2012 and 14.4% in 2024, and the share of children living in districts at 30% or more fell from 20.5% to 4.3%. But it rose by 2 points or more in 2,385 school districts between 2005 to 2007 and 2022 to 2024."
          }
        },
        {
          "@type": "Question",
          "name": "Where is child poverty getting worse?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Among districts with 5,000 or more children, the largest increases were in the industrial Midwest: Youngstown and Warren, OH, Riverview Gardens, MO, and Eastpointe, MI. Detroit had the largest increase among districts with 50,000 or more children."
          }
        },
        {
          "@type": "Question",
          "name": "Why is child poverty so high in the Mississippi Delta?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The data shows how high it is, not why. The 13 Delta districts with full history were between 38.6% and 51.4% in every year from 2005 to 2024, and the region's labor force fell 38.8% since 1990."
          }
        },
        {
          "@type": "Question",
          "name": "What poverty line does this use?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The official federal poverty line. In 2024 it was $31,812 a year for two parents and two children, and $25,273 for one parent and two children, counting income before taxes."
          }
        }
      ]
